#!/usr/bin/env bash
# B4b = B2f with ONE factor changed: + --aug_opus_plc_p 0.3 (in-process libopus round trip with Gilbert-Elliott loss and decoder PLC on 30% of codec calls; --aug_opus_loss 0.01 0.20 and --aug_opus_burst 1 4 left at default)
#   generated by exploop (wave B4, iteration 2) from exploop/B4/iter02/design.result.json
#  B4b = B2f + --aug_opus_plc_p 0.3 (opus_plc arm, iteration b of the B4 screen; rdloop B4 module
#    b4wave). On 30% of codec calls (separate B4 RNG stream), the ffmpeg codec is replaced by an
#    in-process libopus 1.3.1 round trip with the same app/bitrate/cutoff/frame draws,
#    Gilbert-Elliott bursty packet loss (target loss 0.01..0.20, mean burst 1..4 packets; defaults
#    of the coupled flags) and decoder packet-loss concealment at 48 kHz, on both classes. Target:
#    B2f's weakest set, sim_heldout_v1: F1 87.92 / 88.27 (merge / final) with R_bona 69.31 / 69.82
#    against R_spoof 99.00 / 99.13 (B4a report section 2.2). In it, PLC-treated online bona trails
#    untreated online bona: recall 67.5 vs 75.6, G +0.95 (B4a report section 7). B4a raised online
#    heldout spoof misses (half B 5 -> 11 / 4 -> 9), and this arm also tests whether
#    loss-concealment exposure fixes that slice. The mechanism is capped at 'directional'; the arm
#    is an outcome test of ADD-C's PLC result. B4a (apm_ns, verdict drop) is the placebo arm for
#    the PLC contrast. Everything else is B2f's argv, 8 epochs, batch 16, seed 1234.
#  Why: This is the pre-registered iteration b of the B4 screen. wave.json lever_notes say
#    "iterations a-c are the queued arms in this order, apm_ns -> opus_plc -> dtx_gate, each
#    exactly its `set` on top of B2f's argv". plan_snapshot.md row b is `opus_plc`
#    `--aug_opus_plc_p 0.3`. The B4a analyst re-ranked its proposals with opus_plc first
#    (analyze.result.json rank 1). user_notes.md has no steering notes, so the queue order applies.
#    Base = B2f, because new_best_delta 100 keeps B2f as the reference for the whole wave; B4a's
#    verdict was "drop" on both readouts (exploop/B4/iter01/verdict.json), so its flag is not
#    carried over. Evidence. The largest remaining error in the B4a report
#    (docs/experiments-exploration/b4-experiments/20261018_194212_B4a_...md) is still noisy heldout
#    bona: B2f sim_heldout_v1 F1 87.92 / 88.27 (merge / final) with R_bona 69.31 / 69.82 against
#    R_spoof 99.00 / 99.13 (report section 2.2). The report also found that B4a raised online
#    heldout spoof misses on half B (5 -> 11 merge, 4 -> 9 final) and pushed the PLC spoof-miss
#    guard from 16 -> 23 (bound 26). opus_plc targets that slice directly. It is the only B4 lever
#    that changes the codec slot: online sources plus concealment of dropped packets, which B2f
#    never trained on. B2f online PLC-treated vs untreated heldout bona recall is 67.5 / 75.6, G
#    +0.95 (b4_dsp_slices.py via the report, section 7). The apm_ns mechanism was refuted (NS DiD
#    +0.49 > refute line +0.32), so the next step is a different mechanism, not a higher NS dose;
#    analyst proposals 3-4 (apm_ns dose / levels) stay as candidates for iteration d. Constraints.
#    One factor: `--aug_opus_plc_p` is in the coupled group [--aug_opus_plc_p, --aug_opus_loss,
#    --aug_opus_burst], and the loss and burst ranges stay at the trainer defaults (0.01..0.20,
#    1..4) as the plan specifies. The flag is in `allowed`. Nothing forbidden is touched. The fixed
#    flags are unchanged, num_epochs stays 8 (max 10) and batch_size stays 16 per the plan. Trainer
#    preconditions (b4wave/augment.py _init_opus_plc): it needs the codec stage (`--use_rtc_aug`,
#    present) and `--aug_codec_profiles fixed` (the default; the B4a stdout shows `Codec profiles:
#    fixed`). Both hold on the B2f argv. No derived values are needed. The plan pre-registers a
#    zero-loss attribution control (`--aug_opus_plc_p 0.3 --aug_opus_loss 0 0`) for iteration d if
#    this arm is positive on the WF1 CI rule.
#  Hypothesis: Concealment artefacts are read as synthesis. B2f never trained on a dropped packet.
#    Online heldout bona that went through packet-loss concealment trails untreated online bona
#    (recall 67.5 vs 75.6, logit gap +0.95, per the B4a report section 7 and the wave.json
#    lever_queue). On 30% of codec calls, B4b replaces the ffmpeg codec with an in-process libopus
#    round trip using the same app/bitrate/cutoff/frame draws, Gilbert-Elliott bursty loss (target
#    PLR 1-20%, mean burst 1-4 packets) and decoder PLC, on both classes. This should make
#    concealment class-neutral, so heldout bona false alarms on the PLC slice drop and heldout F1
#    rises. The local premise is weak: the typical null-panel PLC gap is smaller (panel mu -0.57,
#    sd 0.41 on DiD), and B4a, which never saw packet loss, already reached online-PLC DiD -0.50
#    (final) / -0.61 (merge). So this arm is mainly a pre-registered outcome test of ADD-C's PLC
#    result in the RTC setting, with the mechanism capped at 'directional'.
#  Expected signature: Mechanism (scripts/b4_dsp_slices.py --lever opus_plc, --ref = B2f's same
#    readout, --placebo = B4a; full sets): online PLC-vs-no-PLC bona DiD < -0.57 (panel mu) on the
#    final readout and below B4a's -0.50 (final) / -0.61 (merge), so it is at least 'directional'.
#    'Shown' (DiD <= -1.39) is not claimed. Report the offline PLC contrast and bona logit/recall
#    by realised-loss bin. Outcome: sim_heldout_v1 F1 up >= 0.5 from 87.92 / 88.27 (merge / final),
#    driven by R_bona rising from 69.31 / 69.82 with R_spoof near 99.00 / 99.13. Expected half_B
#    WF1 delta vs B2f 0 to +0.4 (lever_queue) against 91.98 / 92.14. Must not move:
#    dev_online_clean F1 within 0.5 of 97.60 / 97.69; sim_matched_v1 F1 down <= 0.5 from 91.22 /
#    91.24; matched qq and wechat bona recall each down <= 6 from 61.62 / 71.15; full-set PLC spoof
#    misses <= 26 / 25 (B2f 16 / 15); online heldout spoof misses not above B4a's 11 / 9 on half B;
#    ep1 TrainAcc within 2 of 87.36. Train log: 'Epoch N B3 aug' / 'B4 aug-by-class' lines show
#    opus_plc counts near 0.3 x 75,785 codec calls, balanced across classes, with the plc_l0_5 /
#    plc_l5_10 / plc_l10p bins populated and fail_opus_plc near 0.
#  Eval note: Screen arm: B2f stays the reference (new_best_delta 100). Compare both readouts
#    (merge_top5, epoch_8) with B2f-top5 / B2f-ep8 on the 17 sls_local17 sets with a 2000-sample
#    bootstrap CI. Run scripts/b4_dsp_slices.py --lever opus_plc on merge and final with --ref =
#    B2f's same readout and --placebo = B4a's readout (B4a is now the first placebo arm: its
#    PLC_online DiD is -0.50 final / -0.61 merge, so opus_plc must go below those). Also report the
#    NS and VAD contrasts of this arm, because B4b is a placebo for apm_ns and dtx_gate at the wave
#    SUMMARY. Watch sim_heldout_v1 R_bona (online/PLC slices), the PLC and online heldout spoof
#    misses, matched qq/wechat bona recall, dev_online_clean F1, and fail_opus_plc / plc-bin counts
#    in train.log.
#  Falsification (pre-registered): delta top-5-merge half_B.wf1.wf1 vs B2f merge (91.98) > +0.5
#    with the paired-bootstrap CI excluding 0 and clean F1 drop <= 0.5 -> positive; within +-0.5 ->
#    null; below -0.5 -> negative. (1) Mechanism refuted: online PLC DiD >= -0.57 (DiD* >= 0, no
#    better than an average null retrain) AND heldout F1 delta < +0.5 on either readout: libopus
#    PLC exposure does not carry over to heldout concealment. Drop. (2) half_B WF1 delta < -0.5
#    (below the ±0.5 band) with the shared under-fit signature (ep1 TrainAcc < 85.36 or ep8
#    TrainLoss > 0.0752): a B3d-type codec-side under-fit. Drop. (3) Guard break: full-set PLC
#    spoof misses > 26 (merge) / > 25 (final), matched qq or wechat bona recall down > 6, or clean
#    F1 down > 0.5: concealment became a bona cue, or matched codec fidelity was lost. Drop. (4) A
#    high fail_opus_plc count in the train log: the arm was not dosed as designed (confounded, not
#    refuted). Wave verdict rule: positive = merge half_B WF1 delta > +0.5 with CI low > 0 and
#    clean drop <= 0.5. If positive, iteration d runs the zero-loss control `--aug_opus_plc_p 0.3
#    --aug_opus_loss 0 0`; if that control gives >= half the WF1 gain, the gain goes to the decoder
#    path, not to PLC.
#
#   bash scripts/run_B4b.sh                                   # fresh run (the exploop supervisor launches it)
#   bash scripts/run_B4b.sh --resume exp/<run dir name>       # after a container restart
#   EXPLOOP_PRINT_ARGV=1 bash scripts/run_B4b.sh              # print the trainer argv, launch nothing
#
# Rendered from scripts/exploop/launcher_template.sh (same shape as scripts/run_B3a.sh). Extra
# arguments are appended to the trainer command line. Training runs under nohup; stdout/stderr go to
# <workdir>/<track>_<timestamp>.log and the per-epoch summary to <run dir>/logs/train.log.
set -euo pipefail

PY="${PY:-/root/.conda/envs/rtc-sdd/bin/python}"
TRACK="B4b_qwen17_rtc_musan_loud23_cos8_lr2.5e6_opusplc03_s1234"
WORKDIR="/root/repos/rtc-sdd/Ghostbusters_team/SLS_setup"

ARGS=(
    --train_data_path /mnt/paml-research/RTCFake/data/wav/train
    --train_protocol /mnt/paml-research/RTCFake/data/train_label.txt
    --dev_data_path /mnt/paml-research/RTCFake/data/wav/dev
    --dev_protocol ../data/dev_noisy_sim/dev_label_excl_halfB.txt
    --ssl_name Qwen/Qwen3-ASR-1.7B
    --n_layers 24
    --batch_size 16
    --num_epochs 8
    --num_workers 64
    --use_rtc_aug
    --aug_noise_dirs ../data/augmentation_train/rnnoise ../data/augmentation_train/esc50
    --aug_rir_dirs ../data/augmentation_train/rirs
    --musan
    --musan_dir ../data/augmentation/musan
    --loudness_norm
    --loudness_norm_lufs -23
    --optim adamw
    --lr 2.5e-6
    --head_lr_mult 10
    --weight_decay 0.01
    --lr_scheduler warmup_cosine
    --warmup_frac 0.05
    --lr_min 5e-7
    --grad_clip 1.0
    --ema_decay 0.9995
    --local_eval_sets ../configs/local_eval_sets.yaml
    --earlystop_metric wf1
    --earlystop_epoch 99
    --keep_topk_by_wf1 7
    --keep_epochs 8
    --seed 1234
    --track "$TRACK"
    --aug_opus_plc_p 0.3
)

if [ "${EXPLOOP_PRINT_ARGV:-0}" = "1" ]; then
    printf '%s\n' "${ARGS[@]}"
    exit 0
fi

if [ ! -x "$PY" ]; then
    echo "python not found: $PY (set PY=... to override)" >&2
    exit 1
fi
if ! command -v ffmpeg >/dev/null 2>&1; then
    echo "ffmpeg not found on PATH: the RTC codec augmentation would silently no-op. Reinstall it first." >&2
    exit 1
fi
if ! "$PY" -c "import pyloudnorm" >/dev/null 2>&1; then
    echo "pyloudnorm not importable by $PY: run '$PY -m pip install pyloudnorm==0.2.0' first." >&2
    exit 1
fi

cd "$WORKDIR"
LOG="${TRACK}_$(date +%Y%m%d%H%M%S).log"

nohup "$PY" -u -m b4wave.train "${ARGS[@]}" "$@" > "$LOG" 2>&1 &

PID=$!
echo "Started $TRACK (pid $PID)"
echo "Log:     $WORKDIR/$LOG"
echo "Follow:  tail -f $WORKDIR/$LOG"
echo "Stop:    kill $PID"
